const x=await tools.exec_command({cmd:"python - <<'PY'
from PIL import Image
import numpy as np
im=np.array(Image.open('/app/target.png').convert('L'))<80
A=im[220:800,320:700].copy()
def sh(a,dy,dx):
 p=np.pad(a,1)
 return p[1+dy:1+dy+a.shape[0],1+dx:1+dx+a.shape[1]]
for it in range(100):
 changed=0
 for phase in (0,1):
  p2=sh(A,-1,0); p3=sh(A,-1,1); p4=sh(A,0,1); p5=sh(A,1,1); p6=sh(A,1,0); p7=sh(A,1,-1); p8=sh(A,0,-1); p9=sh(A,-1,-1)
  ns=[p2,p3,p4,p5,p6,p7,p8,p9]
  B=sum(x.astype(np.uint8) for x in ns)
  trans=sum(((~ns[i]) & ns[(i+1)%8]).astype(np.uint8) for i in range(8))
  cond=(B>=2)&(B<=6)&(trans==1)
  if phase==0: cond &= ~(p2&p4&p6)&~(p4&p6&p8)
  else: cond &= ~(p2&p4&p8)&~(p2&p6&p8)
  n=int(cond.sum()); A[cond]=False; changed+=n
 if not changed: break
print('iter',it,'pixels',A.sum())
# enlarge 2x and composite skeleton cyan over crop
base=np.array(Image.open('/app/target.png').convert('RGB'))[220:800,320:700]
out=base.copy(); out[A]=[255,0,0]
Image.fromarray(out).resize((760,1160)).save('/app/skeleton.png')
PY",yield_time_ms:10000,max_output_tokens:100});
